"""Liveness vs readiness demo.

/livez  -> always 200 while the process can serve requests at all.
/readyz -> 200 only when BOTH dependencies are healthy:
             - SQLite reachable (real SELECT 1)
             - job-queue depth < 100
         On failure: 503 with {"checks": {"db": ..., "queue": ...}}
         reporting BOTH checks, never short-circuiting after the first.

Test hooks (dev/test only):
  POST /_test/break-db     swap the connection to a CLOSED one.
                           Call again to repair with a fresh connection.
  POST /_test/flood-queue  push queue depth past the threshold.
                           Optional JSON body {"depth": N}.
                           Call with {"depth": 0} (or no body when already
                           flooded) to drain back to healthy.
"""
import sqlite3

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

QUEUE_LIMIT = 100

app = FastAPI(title="liveness-vs-readiness")


# ------------------------------------------------------------------ state

def new_connection() -> sqlite3.Connection:
    conn = sqlite3.connect("app.db", check_same_thread=False)
    conn.execute("CREATE TABLE IF NOT EXISTS ping (x INTEGER)")
    conn.commit()
    return conn


class State:
    """Holds the dependency handles so tests can sabotage them."""

    def __init__(self) -> None:
        self.db: sqlite3.Connection | None = None
        self.queue: list[int] = []


state = State()


@app.on_event("startup")
def _startup() -> None:
    state.db = new_connection()
    state.queue = []


# ------------------------------------------------------------- check logic

def check_db() -> str:
    """Real SELECT 1 against the current connection."""
    try:
        row = state.db.execute("SELECT 1").fetchone()
        return "ok" if row == (1,) else "fail"
    except Exception:
        return "fail"


def check_queue() -> str:
    return "ok" if len(state.queue) < QUEUE_LIMIT else "fail"


def gather_checks() -> dict[str, str]:
    # Evaluate BOTH checks even if the first fails -- readiness must
    # report the full picture, not stop at the first unhealthy dep.
    return {"db": check_db(), "queue": check_queue()}


# ---------------------------------------------------------------- routes

@app.get("/livez")
def livez():
    # Liveness: is the process itself alive? Dependencies don't matter.
    # If this handler runs at all, we're alive -> always 200.
    return {"status": "alive"}


@app.get("/readyz")
def readyz():
    checks = gather_checks()
    if all(v == "ok" for v in checks.values()):
        return {"status": "ready", "checks": checks}
    return JSONResponse(
        status_code=503,
        content={"status": "unready", "checks": checks},
    )


# ------------------------------------------------------------ test hooks

@app.post("/_test/break-db")
def break_db():
    if state.db is not None:
        try:
            state.db.execute("SELECT 1")
            healthy = True
        except Exception:
            healthy = False
    else:
        healthy = False

    if healthy:
        # Break: replace with a closed connection.
        state.db.close()
        state.db = sqlite3.connect("app.db", check_same_thread=False)
        state.db.close()
        return {"db": "broken"}
    # Already broken -> repair with a fresh working connection.
    state.db = new_connection()
    return {"db": "repaired"}


@app.post("/_test/flood-queue")
async def flood_queue(request: Request):
    body = await request.json() if await request.body() else {}
    depth = int(body.get("depth", QUEUE_LIMIT + 50))
    state.queue = list(range(max(0, depth)))
    return {"queue_depth": len(state.queue)}

